', 'public class Solution {
    public static boolean isPalindrome(int x) {
        if (x < 0) return false;
        int rev = 0, orig = x;
        while (x > 0) {
            rev = rev * 10 + x % 10;
            x /= 10;
        }
        return rev == orig;
    }
}
', '#include <stdbool.h>

bool isPalindrome(int x) {
    if (x < 0) return false;
    long rev = 0, orig = x;
    while (x > 0) {
        rev = rev * 10 + x % 10;
        x /= 10;
    }
    return rev == orig;
}
